const w=[1,2,3];function m(e,n){return n===0?0:Math.round(e/n*100)}function M(e,n){return e>0&&n===0}function S(e,n,l){const d=new Set(n.map(t=>t.id)),f=[],g=new Map;for(const t of e){if(t.lang==="common")continue;let o=g.get(t.lang);o||(o=new Map,g.set(t.lang,o),f.push(t.lang));const c=t.lessons.filter(s=>d.has(s.id));o.set(t.stage,{learned:c.filter(s=>l.has(s.id)).length,total:c.length})}return f.map(t=>{const o=g.get(t),c=w.map(r=>{const a=o.get(r)?.learned??0,u=o.get(r)?.total??0,p=u-a;return{stage:r,learned:a,total:u,percent:m(a,u),missing:p,done:M(u,p)}}),s=c.reduce((r,a)=>r+a.learned,0),i=c.reduce((r,a)=>r+a.total,0),h=i-s;return{lang:t,learned:s,total:i,percent:m(s,i),missing:h,done:M(i,h),stages:c}})}function L(e,n){if(n.length===0)return 0;let l=0;for(const d of n)e.has(d.id)&&l++;return Math.round(l/n.length*100)}export{S as c,L as o};
